from django.db import migrations

SQL="-- Case-local topology and typed completion are protected even from raw SQL.\nCREATE OR REPLACE FUNCTION public.m2_validate_task_edge()\nRETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$\nDECLARE p uuid; s uuid;\nBEGIN\n SELECT case_id INTO p FROM public.onboarding_task WHERE id=NEW.predecessor_id FOR SHARE;\n SELECT case_id INTO s FROM public.onboarding_task WHERE id=NEW.successor_id FOR SHARE;\n IF p IS DISTINCT FROM NEW.case_id OR s IS DISTINCT FROM NEW.case_id THEN\n   RAISE EXCEPTION 'cross-case task dependency' USING ERRCODE='23514';\n END IF;\n RETURN NEW;\nEND; $$;\nCREATE TRIGGER m2_task_edge_guard BEFORE INSERT OR UPDATE OF case_id,predecessor_id,successor_id\nON public.onboarding_taskdependency FOR EACH ROW EXECUTE FUNCTION public.m2_validate_task_edge();\n\nCREATE OR REPLACE FUNCTION public.m2_validate_task_completion()\nRETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$\nDECLARE t uuid; k text;\nBEGIN\n SELECT a.task_id INTO t FROM public.onboarding_managerattestation a\n WHERE a.id=NEW.manager_attestation_id FOR SHARE;\n SELECT kind INTO k FROM public.onboarding_task WHERE id=NEW.task_id FOR SHARE;\n IF t IS DISTINCT FROM NEW.task_id OR k IS DISTINCT FROM 'MANAGER_PREPARATION'\n    OR NEW.evidence_type IS DISTINCT FROM 'MANAGER_PREPARATION' THEN\n   RAISE EXCEPTION 'invalid manager evidence task' USING ERRCODE='23514';\n END IF;\n RETURN NEW;\nEND; $$;\nCREATE TRIGGER m2_completion_guard BEFORE INSERT OR UPDATE OF task_id,manager_attestation_id,evidence_type\nON public.onboarding_taskcompletion FOR EACH ROW EXECUTE FUNCTION public.m2_validate_task_completion();\n\nCREATE OR REPLACE FUNCTION public.m2_validate_template_edge()\nRETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$\nDECLARE p uuid; s uuid;\nBEGIN\n SELECT version_id INTO p FROM public.templates_templatetask WHERE id=NEW.predecessor_id FOR SHARE;\n SELECT version_id INTO s FROM public.templates_templatetask WHERE id=NEW.successor_id FOR SHARE;\n IF p IS DISTINCT FROM NEW.version_id OR s IS DISTINCT FROM NEW.version_id THEN\n   RAISE EXCEPTION 'cross-version template edge' USING ERRCODE='23514';\n END IF;\n RETURN NEW;\nEND; $$;\nCREATE TRIGGER m2_template_edge_guard BEFORE INSERT OR UPDATE OF version_id,predecessor_id,successor_id\nON public.templates_templatedependency FOR EACH ROW EXECUTE FUNCTION public.m2_validate_template_edge();\n\nCREATE OR REPLACE FUNCTION public.m2_block_published_version()\nRETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$\nBEGIN\n IF TG_OP='DELETE' OR (OLD.state='PUBLISHED' AND NEW IS DISTINCT FROM OLD) THEN\n   RAISE EXCEPTION 'published template versions immutable' USING ERRCODE='23514';\n END IF;\n RETURN NEW;\nEND; $$;\nCREATE TRIGGER m2_version_immutable BEFORE UPDATE OR DELETE\nON public.templates_templateversion FOR EACH ROW EXECUTE FUNCTION public.m2_block_published_version();\n\nCREATE OR REPLACE FUNCTION public.m2_block_published_child()\nRETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$\nDECLARE vid uuid; state text;\nBEGIN\n vid=CASE WHEN TG_OP='DELETE' THEN OLD.version_id ELSE NEW.version_id END;\n SELECT v.state INTO state FROM public.templates_templateversion v WHERE v.id=vid FOR SHARE;\n IF state='PUBLISHED' THEN\n   RAISE EXCEPTION 'published template content immutable' USING ERRCODE='23514';\n END IF;\n IF TG_OP='UPDATE' AND OLD.version_id IS DISTINCT FROM NEW.version_id THEN\n   RAISE EXCEPTION 'template task/edge version reparent forbidden' USING ERRCODE='23514';\n END IF;\n RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;\nEND; $$;\nCREATE TRIGGER m2_task_template_immutable BEFORE INSERT OR UPDATE OR DELETE\nON public.templates_templatetask FOR EACH ROW EXECUTE FUNCTION public.m2_block_published_child();\nCREATE TRIGGER m2_edge_template_immutable BEFORE INSERT OR UPDATE OR DELETE\nON public.templates_templatedependency FOR EACH ROW EXECUTE FUNCTION public.m2_block_published_child();"
REVERSE_SQL="DROP TRIGGER IF EXISTS m2_edge_template_immutable ON public.templates_templatedependency;\nDROP TRIGGER IF EXISTS m2_task_template_immutable ON public.templates_templatetask;\nDROP FUNCTION IF EXISTS public.m2_block_published_child();\nDROP TRIGGER IF EXISTS m2_version_immutable ON public.templates_templateversion;\nDROP FUNCTION IF EXISTS public.m2_block_published_version();\nDROP TRIGGER IF EXISTS m2_template_edge_guard ON public.templates_templatedependency;\nDROP FUNCTION IF EXISTS public.m2_validate_template_edge();\nDROP TRIGGER IF EXISTS m2_completion_guard ON public.onboarding_taskcompletion;\nDROP FUNCTION IF EXISTS public.m2_validate_task_completion();\nDROP TRIGGER IF EXISTS m2_task_edge_guard ON public.onboarding_taskdependency;\nDROP FUNCTION IF EXISTS public.m2_validate_task_edge();"

